+    private Insets insets = Insets.EMPTY;
+    private boolean snapToPixel = true;
+    private Snapper snapper = Snapper.createSnapper(renderScaleContext);
+
+    private double x;
+    private double y;
+    private double w;
+    private double h;
+
+    private boolean biasDirty = true;
+    private Orientation bias;
