+            updateSnapper();
+        }
+    }
+
+    void invalidate() {
+        this.biasDirty = true;
+        this.bias = null;
+    }
+
+    @Override
+    public boolean isResizable() {
+        return true;
+    }
+
+    @Override
+    public Orientation getContentBias() {
+        if (biasDirty) {
+            bias = null;
+
+            for (Layoutable child : children) {
+                Orientation contentBias = child.getContentBias();
+
+                if (contentBias != null) {
+                    bias = contentBias;
+
+                    if (contentBias == Orientation.HORIZONTAL) {
+                        break;
+                    }
+                }
+            }
+
+            biasDirty = false;
+        }
+
+        return bias;
+    }
